 'plus':'<path d="M12 5v14M5 12h14"/>', 'shuffle':'<path d="m18 14 4 4-4 4M2 18h3c7 0 7-12 14-12h3M18 2l4 4-4 4M2 6h3c2.5 0 4 1.6 5 3M14 15c1 1.7 2.4 3 5 3h3"/>',
 'refresh-cw':'<path d="M20 11a8 8 0 1 0-2 6M20 4v7h-7"/>','lock':'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
